import {emptyProject,makeTrack} from '../../web-studio/model.js';
export function regionTrimProject(){const p=emptyProject();p.name='Group trim proof';p.tracks.push(makeTrack('Second'),makeTrack('Unchanged'));p.tracks.forEach((t,i)=>t.id='trim-track-'+i);p.clips.c={id:'c',name:'Phrase',kind:'midi',sourceBpm:120,beats:4,notes:[{pitch:60,start:.5,duration:1,velocity:.8}]};p.arrangement=[{id:'a',trackId:p.tracks[0].id,clipId:'c',start:4,length:4,offset:1},{id:'b',trackId:p.tracks[1].id,clipId:'c',start:8,length:2,offset:3},{id:'far',trackId:p.tracks[2].id,clipId:'c',start:30,length:4,offset:0}];return p;}
